// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;

    // accept ETH as the bank without reverting
    receive() external payable {}

    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 ts, address player) public {
        vm.assume(player != address(0) && player != address(c) && player != address(this));
        ts = bound(ts, 0, 2 ** 64);
        vm.warp(ts);

        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();

        // Rule: after any successful play, pot is always a whole number of tickets.
        // Reference: win -> pot = 0; loss -> pot = 10. Mutant: win -> pot = 1.
        assertTrue(c.pot() % 10 == 0);
    }
}
